  "APIBaseURL": "https://www.eventbriteapi.com/v3",
  "AuthFlow": "oauth2-authcode",
  "AuthFlowNotes": "Two paths: (1) Private token — issued from the Eventbrite account API Keys page, used as a long-lived Bearer token for single-org integrations. (2) OAuth2 authorization-code flow for app partners acting on behalf of multiple users. Authorization URL: https://www.eventbrite.com/oauth/authorize?response_type=code&client_id=YOUR_API_KEY&redirect_uri=YOUR_REDIRECT_URI. Token URL: POST https://www.eventbrite.com/oauth/token (grant_type=authorization_code; body params: client_id, client_secret, code, redirect_uri). Both flows produce a private token/access token used as Authorization: Bearer <token>. The connector credential holds the resolved token; the grant-type path is the AuthFlow shape here.",
  "AuthHeaderPattern": "Authorization: Bearer <token>",
  "TokenRefreshStrategy": "none",
  "TokenRefreshStrategyNotes": "Private tokens do not expire. OAuth2 access tokens (from the authorization-code flow) also do not have a documented expiry / refresh-token mechanism in the v3 API spec. Vendor docs describe only an initial token exchange; no refresh token endpoint is documented. Token must be re-obtained by re-running the authorization-code flow.",
  "APIVersioningStrategy": "url-path",
  "APIVersioningStrategyNotes": "Version is embedded in the URL path as /v3/ (e.g. https://www.eventbriteapi.com/v3/events/). No version header or accept-header versioning. The apiary.io spec is tagged as Eventbrite API v3; no other public major versions are currently documented.",
  "PaginationDefaults": {
    "style": "continuation-cursor",
